import csv
import io
import json

_FIELDS = ("id", "name")


def _normalize(rows):
    """Reduce each row to (id, name) strings, preserving input order.

    Missing or None values become ''; other values are stringified. Each row
    is read once and never modified, and a one-shot iterable is consumed once.
    """
    return [
        tuple("" if row.get(key) is None else str(row[key]) for key in _FIELDS)
        for row in rows
    ]


def _serialize_csv(records):
    buffer = io.StringIO(newline="")
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(_FIELDS)
    writer.writerows(records)
    return buffer.getvalue()


def _serialize_json(records):
    payload = [dict(zip(_FIELDS, record)) for record in records]
    return json.dumps(payload, ensure_ascii=False, separators=(",", ":"))


def export_rows(rows, format):
    """Export rows as 'csv' or 'json'. Raises ValueError for other formats."""
    # Check the format before touching rows so a one-shot iterable is left
    # untouched on error. Use == (not a dict lookup) so unhashable formats
    # also raise ValueError.
    if format == "csv":
        return _serialize_csv(_normalize(rows))
    if format == "json":
        return _serialize_json(_normalize(rows))
    raise ValueError("unsupported format")
